using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Security;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Modules;[Authorize(Policy="SuperAdminOnly")]public sealed class NewModel(OrcaFacilDbContext db):PageModel{[BindProperty]public ModuleInput Input{get;set;}=new();public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(!PermissionCodes.All.Contains(Input.Permission))ModelState.AddModelError("Input.Permission","Use uma permissão registrada no backend.");if(await db.SaasModules.AnyAsync(x=>x.Code==Input.Code&&!x.IsDeleted,ct))ModelState.AddModelError("Input.Code","Código já cadastrado.");if(!ModelState.IsValid)return Page();var module=new SaasModule{Code=Input.Code,DisplayName=Input.DisplayName,Description=Input.DisplayName,Category=Input.Category,MenuGroup=Input.MenuGroup,RoutePrefix=Input.RoutePrefix,RequiredPermissionCode=Input.Permission,BaseMonthlyPrice=Input.MonthlyPrice,BaseAnnualPrice=Input.AnnualPrice};db.SaasModules.Add(module);db.SaasModulePrices.AddRange(new(){ModuleId=module.Id,BillingPeriod=SaasBillingPeriod.Monthly,Amount=Input.MonthlyPrice,ValidFrom=DateTime.UtcNow},new(){ModuleId=module.Id,BillingPeriod=SaasBillingPeriod.Annual,Amount=Input.AnnualPrice,ValidFrom=DateTime.UtcNow});Audit(module,"GlobalModuleCreated");await db.SaveChangesAsync(ct);return RedirectToPage("Edit",new{id=module.Id});}private void Audit(SaasModule m,string action)=>db.AccountModuleAuditLogs.Add(new(){ActorUserId=Guid.TryParse(User.FindFirstValue("user_id"),out var x)?x:Guid.Empty,Action=action,EntityType=nameof(SaasModule),EntityId=m.Id.ToString(),ModuleCode=m.Code,Summary="Módulo e preços criados.",CorrelationId=HttpContext.TraceIdentifier});}
